package com.smarthealth.model;
import java.time.LocalDate; import java.util.Objects;
/** A medicine prescription and its schedule. */
public class Medicine {private long id,patientId;private String name,dosage,instructions,frequency;private LocalDate startDate,endDate;
 public Medicine(){} public Medicine(long id,long patientId,String name,String dosage,String instructions,LocalDate startDate,LocalDate endDate,String frequency){this.id=id;this.patientId=patientId;setName(name);this.dosage=dosage;this.instructions=instructions;this.startDate=startDate;this.endDate=endDate;this.frequency=frequency;}
 public long getId(){return id;}public void setId(long v){id=v;}public long getPatientId(){return patientId;}public void setPatientId(long v){patientId=v;}public String getName(){return name;}public void setName(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("Medicine name required");name=v;}public String getDosage(){return dosage;}public void setDosage(String v){dosage=v;}public String getInstructions(){return instructions;}public void setInstructions(String v){instructions=v;}public String getFrequency(){return frequency;}public void setFrequency(String v){frequency=v;}public LocalDate getStartDate(){return startDate;}public void setStartDate(LocalDate v){startDate=v;}public LocalDate getEndDate(){return endDate;}public void setEndDate(LocalDate v){endDate=v;}
 @Override public String toString(){return name+" ("+dosage+")";}@Override public boolean equals(Object o){return o instanceof Medicine m&&id==m.id;}@Override public int hashCode(){return Objects.hash(id);}}
